<?php
require __DIR__.'/bootstrap.php';
$roomId=require_room_id($_GET['room']??'');canonicalize_get_route('journey',$roomId);$room=$store->get($roomId);$pid=participant_id_for($roomId);
if(!$room||!$pid||empty($room['participants'][$pid]['verified_at'])){header('Location: '.route_url('join',$roomId));exit;}
$p=$room['participants'][$pid];$cards=journey_for_participant($p);if(!$cards){header('Location: '.route_url('join',$roomId));exit;}
