$seedJson=json_encode($seed,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);if(!is_string($seedJson))$seedJson='{}';
?><!doctype html><html data-room="<?=h($roomId)?>" data-csrf="<?=h($csrf)?>" data-answer-url="<?=h(route_url('answer',$roomId))?>" data-complete-url="<?=h(route_url('complete',$roomId))?>" data-reflection-ms="<?=intval(($config['card_reflection_seconds']??3)*1000)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Your <?=intval($total)?>-card journey · Udaan</title><?=common_assets_head('#141510')?></head><body class="journey-page"><div class="floating-theme journey-theme"><?=theme_toggle()?></div><div class="offline-badge">Offline · answers are being kept on this device</div><main class="journey">
